def myhash(key, n):
    h = 0
    for ch in key:
        h = (h * 31 + ord(ch)) & 0x7fffffff
    return h % n

pairs = [("world",1),("hello",1),("bigdata",1),("hello",1),("world",1),("bigdata",1),("hello",1),("of",1),("world",1)]
R = 3
buckets = {r: [] for r in range(R)}
for k, v in pairs:
    buckets[myhash(k, R)].append((k, v))
for r in range(R):
    buckets[r].sort(key=lambda x: x[0])
    print(f"partition {r}: {buckets[r]}")
